draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // brain
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 150 + 50 * Math.sin(t), H/2 - 50 - 20 * Math.cos(t), 50, 0, 2 * Math.PI);
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 120, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 140);
  ctx.lineTo(W/2, H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 160);
  ctx.lineTo(W/2 - 30, H/2 + 180);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 160);
  ctx.lineTo(W/2 + 30, H/2 + 180);
  ctx.stroke();

  // eyes
  ctx.beginPath();
  ctx.arc(W/2 - 5, H/2 + 110, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 5, H/2 + 110, 5, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
